 @Override public void onCreate(Bundle b){super.onCreate(b);db=new AutoDb(this);light=getPreferences(0).getBoolean("light",false);lang=getPreferences(0).getString("lang","ru");active=getPreferences(0).getLong("active",-1);if(active<0){Cursor c=db.raw("SELECT id FROM vehicle ORDER BY id LIMIT 1",null);try{if(c.moveToFirst())active=c.getLong(0);}finally{c.close();}}themeBars();build();if(active<0)showWelcome();else home();MileageReminderWorker.ensure(this);DocumentReminderWorker.ensure(this);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},777);}
 void themeBars(){int bg=light?Color.rgb(242,245,248):Color.rgb(7,9,13);getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(bg);getWindow().getDecorView().setSystemUiVisibility(light?(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR):0);}
 String t(String ru,String en){return "en".equals(lang)?en:ru;}
 int bg(){return light?Color.rgb(242,245,248):Color.rgb(7,9,13);}int fg(){return light?Color.rgb(25,31,38):Color.rgb(245,248,252);}int sub(){return light?Color.rgb(88,101,115):Color.rgb(150,166,184);}int surface(){return light?Color.rgb(248,250,252):Color.rgb(12,18,26);} 
 GradientDrawable glass(int stroke){GradientDrawable g=new GradientDrawable();g.setColor(light?0xEAFBFCFE:0xC9141D27);g.setCornerRadius(dp(20));g.setStroke(dp(1),light?0xB9FFFFFF:0x8863A9E7);return g;}
 TextView text(String s,float size,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextColor(fg());v.setTextSize(size);v.setTypeface(Typeface.DEFAULT,bold?Typeface.BOLD:Typeface.NORMAL);v.setIncludeFontPadding(true);return v;}
 TextView small(String s){TextView v=text(s,12,false);v.setTextColor(sub());return v;}
 Button btn(String s,int accent){Button b=new Button(this);b.setText(s);b.setTextColor(Color.WHITE);b.setTextSize(13);b.setAllCaps(false);GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT,new int[]{accent,Color.rgb(16,104,218)});g.setCornerRadius(dp(15));b.setBackground(g);b.setMinHeight(dp(48));return b;}
 LinearLayout card(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(dp(16),dp(14),dp(16),dp(14));l.setBackground(glass(1));l.setElevation(dp(3));return l;}
