 int dp(int x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
 void build(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(bg());content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(dp(16),dp(12),dp(16),dp(24));ScrollView sv=new ScrollView(this);sv.setFillViewport(true);sv.addView(content);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));nav=new LinearLayout(this);nav.setGravity(Gravity.CENTER);nav.setPadding(dp(8),dp(6),dp(8),dp(8));nav.setBackground(glass(1));root.addView(nav,new LinearLayout.LayoutParams(-1,dp(66)));setContentView(root);}
 void nav(){nav.removeAllViews();String[] a={t("Главная","Home"),t("Обслуживание","Service"),t("Финансы","Finance"),t("Авто","Auto"),t("Ещё","More")};for(int i=0;i<a.length;i++){final int p=i;TextView v=text(a[i],10,false);v.setGravity(Gravity.CENTER);v.setTextColor(sub());v.setPadding(0,dp(7),0,dp(5));if((screen==p))v.setTextColor(blue);nav.addView(v,new LinearLayout.LayoutParams(0,-1,1));v.setOnClickListener(x->{screen=p;render();});}}
 int screen=0; int periodDays=0; String pendingAttachment=""; void render(){build();if(screen==0)home();else if(screen==1)serviceScreen();else if(screen==2)financeScreen();else if(screen==3)autoScreen();else moreScreen();nav();}
 String val(String key,String def){Cursor c=db.raw("SELECT "+key+" FROM vehicle WHERE id=?",new String[]{String.valueOf(active)});try{return c.moveToFirst()?c.getString(0):def;}finally{c.close();}}
 double num(String s){try{return Double.parseDouble((s==null?"":s).replace(" ","").replace(",","."));}catch(Exception e){return 0;}}
 String today(){return new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());}
 void showWelcome(){build();TextView logo=text("AUTO HUB",31,true);logo.setGravity(Gravity.CENTER);logo.setTextColor(Color.WHITE);content.setGravity(Gravity.CENTER_HORIZONTAL);addGap(60);add(logo);TextView sl=small("Ваш автомобиль —\n"+t("под контролем.","under control."));sl.setGravity(Gravity.CENTER);add(sl);addGap(35);TextView car=text("▰",95,true);car.setGravity(Gravity.CENTER);car.setTextColor(blue);add(car);addGap(20);Button b=btn(t("Начать","Start"),blue);b.setOnClickListener(v->onboarding());add(b);TextView f=small(t("Управляйте. Следите. Экономьте.","Manage. Track. Save."));f.setGravity(Gravity.CENTER);addGap(14);add(f);nav.setVisibility(View.GONE);}
 void onboarding(){build();TextView h=text(t("Добавьте автомобиль","Add vehicle"),28,true);add(h);add(small(t("Минимально обязательны марка, модель и текущий пробег.","Brand, model and current mileage are required.")));addGap(16);vehicleDialog(true);}
 void vehicleDialog(boolean first){final LinearLayout l=form();EditText brand=input(t("Марка","Brand"),first?"":val("brand",""));EditText model=input(t("Модель","Model"),first?"":val("model",""));EditText year=input(t("Год выпуска","Year"),first?"":val("year",""));EditText engine=input(t("Двигатель","Engine"),first?"":val("engine",""));EditText gear=input(t("Коробка передач","Gearbox"),first?"":val("gear",""));EditText mileage=input(t("Текущий пробег, км","Current mileage, km"),first?"0":val("mileage","0"));mileage.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);EditText vin=input("VIN",first?"":val("vin",""));EditText plate=input(t("Госномер","Plate"),first?"":val("plate",""));EditText fuel=input(t("Тип топлива","Fuel type"),first?"":val("fuelType",""));Button photo=btn(t("Добавить фото автомобиля","Add vehicle photo"),Color.rgb(64,103,145));l.addView(photo);photo.setOnClickListener(v->pickPhoto());Button save=btn(t("Сохранить автомобиль","Save vehicle"),blue);l.addView(brand);l.addView(model);l.addView(year);l.addView(engine);l.addView(gear);l.addView(mileage);l.addView(vin);l.addView(plate);l.addView(fuel);l.addView(save);add(l);save.setOnClickListener(v->{if(brand.getText().toString().trim().isEmpty()||model.getText().toString().trim().isEmpty()||num(mileage.getText().toString())<0){toast(t("Заполните марку, модель и корректный пробег","Enter brand, model and a valid mileage"));return;}ContentValues x=new ContentValues();x.put("brand",brand.getText().toString().trim());x.put("model",model.getText().toString().trim());x.put("year",(int)num(year.getText().toString()));x.put("engine",engine.getText().toString().trim());x.put("gear",gear.getText().toString().trim());x.put("mileage",num(mileage.getText().toString()));x.put("vin",vin.getText().toString().trim());x.put("plate",plate.getText().toString().trim());x.put("fuelType",fuel.getText().toString().trim());String chosenPhoto=attachment();x.put("photo",chosenPhoto.isEmpty()?(first?"":val("photo","")):chosenPhoto);x.put("createdAt",System.currentTimeMillis());if(first){active=db.addVehicle(x);getPreferences(0).edit().putLong("active",active).apply();db.log(active,"AUTO","Автомобиль добавлен",brand.getText()+" "+model.getText());screen=0;render();}else{double oldKm=num(val("mileage","0")),newKm=num(mileage.getText().toString());if(newKm<oldKm){new AlertDialog.Builder(this).setTitle("Пробег меньше текущего").setMessage("Новый пробег меньше сохранённого. Изменить его всё равно?").setNegativeButton("Отмена",null).setPositiveButton("Изменить",(dd,ww)->{db.update("vehicle",x,"id=?",new String[]{String.valueOf(active)});render();}).show();}else{db.update("vehicle",x,"id=?",new String[]{String.valueOf(active)});toast(t("Автомобиль сохранён","Vehicle saved"));render();}}});nav.setVisibility(View.GONE);}
 LinearLayout form(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
 EditText input(String hint,String value){EditText e=new EditText(this);e.setHint(hint);e.setText(value);e.setTextColor(fg());e.setHintTextColor(sub());e.setTextSize(15);e.setSingleLine(true);e.setPadding(dp(14),0,dp(14),0);GradientDrawable g=new GradientDrawable();g.setColor(light?0xFFFFFFFF:0xAA0A111A);g.setCornerRadius(dp(13));g.setStroke(dp(1),light?0x33000000:0x665B8FBD);e.setBackground(g);e.setLayoutParams(new LinearLayout.LayoutParams(-1,dp(50)){{setMargins(0,0,0,dp(8));}});return e;}
 void header(String title,String subline){TextView h=text(title,27,true);add(h);if(subline!=null)add(small(subline));addGap(12);}
 void home(){if(active<0){showWelcome();return;}String vehicle=val("brand","")+" "+val("model","");header("AUTO HUB",vehicle.trim());LinearLayout hero=card();TextView ht=text(vehicle.trim(),21,true);hero.addView(ht);ImageView car=new ImageView(this);String carUri=val("photo","");if(carUri.isEmpty())car.setImageResource(R.drawable.car_placeholder);else try{String resolved=resolveAttachment(carUri);if(resolved.startsWith("/"))car.setImageURI(Uri.fromFile(new File(resolved)));else car.setImageURI(Uri.parse(resolved));}catch(Exception ignored){car.setImageResource(R.drawable.car_placeholder);}car.setAdjustViewBounds(true);hero.addView(car,new LinearLayout.LayoutParams(-1,dp(110)));hero.addView(small((val("year","").equals("0")?"":val("year",""))+" · "+(val("engine","").isEmpty()?t("Двигатель не указан","Engine not specified"):val("engine",""))+" · "+(val("gear","").isEmpty()?t("КПП не указана","Gearbox not specified"):val("gear",""))));LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);TextView km=text(fmt(num(val("mileage","0")))+" км",31,true);row.addView(km,new LinearLayout.LayoutParams(0,dp(70),1));TextView status=text(healthText(),12,true);status.setTextColor(healthColor());status.setGravity(Gravity.CENTER);row.addView(status,new LinearLayout.LayoutParams(dp(110),dp(50)));hero.addView(row);add(hero);addGap(12);sectionTitle(t("Следующее ТО","Next service"));String next=nextService();add(infoCard(next,blue));addGap(10);sectionTitle(t("Быстрые действия","Quick actions"));LinearLayout q=new LinearLayout(this);q.setOrientation(LinearLayout.VERTICAL);q.addView(actionRow(new String[]{"+ ТО","+ Заправка","+ Расход"},new View.OnClickListener[]{v->serviceDialog(),v->fuelDialog(),v->expenseDialog()}));q.addView(actionRow(new String[]{"+ Напоминание","+ Проблема","+ Шины"},new View.OnClickListener[]{v->reminderDialog(),v->issueDialog(),v->tireDialog()}));add(q);addGap(10);sectionTitle(t("Ключевые показатели","Key metrics"));LinearLayout m=new LinearLayout(this);m.setOrientation(LinearLayout.HORIZONTAL);m.addView(metric(t("Расход","Consumption"),consumption(),"л/100 км"),new LinearLayout.LayoutParams(0,dp(105),1));m.addView(metric(t("Расходы","Expenses"),money(totalExpenses()),"₽"),new LinearLayout.LayoutParams(0,dp(105),1));m.addView(metric(t("Стоимость/км","Cost/km"),costKm(),"₽/км"),new LinearLayout.LayoutParams(0,dp(105),1));add(m);addGap(10);sectionTitle(t("Последняя активность","Recent activity"));activityCards(3);addGap(10);Button manage=btn(t("Открыть полный журнал","Open activity"),blue);manage.setOnClickListener(v->{screen=4;render();});add(manage);}
 View metric(String title,String value,String unit){LinearLayout c=card();c.setPadding(dp(11),dp(10),dp(11),dp(10));c.addView(small(title));TextView b=text(value,18,true);b.setPadding(0,dp(5),0,0);c.addView(b);c.addView(small(unit));return c;}
 View actionRow(String[] labels,View.OnClickListener[] ls){LinearLayout r=new LinearLayout(this);for(int i=0;i<3;i++){Button b=btn(labels[i],i==0?blue:(i==1?Color.rgb(0,177,145):Color.rgb(240,154,44)));b.setTextSize(11);b.setOnClickListener(ls[i]);r.addView(b,new LinearLayout.LayoutParams(0,dp(52),1){{setMargins(dp(3),dp(3),dp(3),dp(3));}});}return r;}
 void sectionTitle(String s){TextView h=text(s,18,true);h.setPadding(0,dp(3),0,dp(6));add(h);}
 TextView infoCard(String s,int color){TextView v=text(s,13,true);v.setPadding(dp(16),dp(16),dp(16),dp(16));GradientDrawable g=glass(1);g.setStroke(dp(1),color);v.setBackground(g);return v;}
 void activityCards(int n){Cursor c=db.raw("SELECT kind,title,detail,date,time FROM activity WHERE vehicleId=? ORDER BY createdAt DESC LIMIT ?",new String[]{String.valueOf(active),String.valueOf(n)});try{while(c.moveToNext()){LinearLayout x=card();x.addView(text(c.getString(1),14,true));x.addView(small(c.getString(3)+" · "+c.getString(4)+" · "+c.getString(2)));x.addView(small(c.getString(3)));add(x);addGap(7);}}finally{c.close();}}
 String nextService(){Cursor c=db.raw("SELECT title,nextDate,nextMileage,mileage FROM service WHERE vehicleId=? AND (nextMileage>0 OR nextDate<>'') ORDER BY id DESC",new String[]{String.valueOf(active)});try{if(!c.moveToFirst())return t("Нет запланированного обслуживания","No planned service");String title=c.getString(0);double nk=c.getDouble(2);String nd=c.getString(1);if(nk>0)return title+" · "+fmt(nk)+" км";return title+" · "+nd;}finally{c.close();}}
 String healthText(){Cursor d=db.raw("SELECT expiryDate FROM document WHERE vehicleId=? AND expiryDate<>''",new String[]{String.valueOf(active)});try{while(d.moveToNext())if(d.getString(0).compareTo(today())<0)return t("КРИТИЧНО","CRITICAL");}finally{d.close();}Cursor svc=db.raw("SELECT nextMileage,nextDate FROM service WHERE vehicleId=?",new String[]{String.valueOf(active)});double currentKm=num(val("mileage","0"));try{while(svc.moveToNext()){double nk=svc.getDouble(0);String nd=svc.getString(1);if((nk>0&&currentKm>=nk)||(nd!=null&&!nd.isEmpty()&&nd.compareTo(today())<0))return t("ПРОСРОЧЕНО","OVERDUE");}}finally{svc.close();}Cursor r=db.raw("SELECT COUNT(*) FROM reminder WHERE vehicleId=? AND done=0 AND date<?",new String[]{String.valueOf(active),today()});try{if(r.moveToFirst()&&r.getInt(0)>0)return t("ПРОСРОЧЕНО","OVERDUE");}finally{r.close();}Cursor p=db.raw("SELECT COUNT(*) FROM issue WHERE vehicleId=? AND status IN ('NEW','DIAGNOSIS','REPAIR')",new String[]{String.valueOf(active)});try{if(p.moveToFirst()&&p.getInt(0)>0)return t("ВНИМАНИЕ","ATTENTION");}finally{p.close();}return t("НОРМА","NORMAL");}
 int healthColor(){String h=healthText();return h.contains("КРИТ")||h.equals("CRITICAL")?Color.rgb(255,74,88):(h.contains("ПРОС")||h.equals("OVERDUE")||h.contains("ВНИМ")||h.equals("ATTENTION")?Color.rgb(255,171,58):Color.rgb(40,207,147));}
 double sumPeriod(String table,String col){if(periodDays<=0)return sum(table,col);String since=new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date(System.currentTimeMillis()-periodDays*86400000L));Cursor c=db.raw("SELECT COALESCE(SUM("+col+"),0) FROM "+table+" WHERE vehicleId=? AND date>=?",new String[]{String.valueOf(active),since});try{return c.moveToFirst()?c.getDouble(0):0;}finally{c.close();}}
double totalExpenses(){return sum("expense","amount")+sum("fuel","total")+sum("service","cost");}
 double sum(String table,String col){Cursor c=db.raw("SELECT COALESCE(SUM("+col+"),0) FROM "+table+" WHERE vehicleId=?",new String[]{String.valueOf(active)});try{return c.moveToFirst()?c.getDouble(0):0;}finally{c.close();}}
 String money(double x){return x<0?t("Некорректно","Invalid"):String.format(Locale.getDefault(),"%.0f",x);}
 String consumption(){Cursor c=db.raw("SELECT mileage,liters,fullTank FROM fuel WHERE vehicleId=? ORDER BY mileage,id",new String[]{String.valueOf(active)});double anchorKm=-1,fuelSince=0,totalLit=0,totalDist=0;try{while(c.moveToNext()){double km=c.getDouble(0),l=c.getDouble(1);boolean full=c.getInt(2)!=0;if(km<0||l<0)continue;if(full){if(anchorKm>=0&&km>anchorKm){totalDist+=km-anchorKm;totalLit+=fuelSince+l;}anchorKm=km;fuelSince=0;}else if(anchorKm>=0){fuelSince+=l;}}}finally{c.close();}return totalDist<=0?t("Недостаточно данных","Not enough data"):String.format(Locale.getDefault(),"%.1f",CarMath.consumption(totalLit,totalDist));}
 String costKm(){double dist=distance();return dist<=0?t("Недостаточно данных","Not enough data"):String.format(Locale.getDefault(),"%.2f",CarMath.costPerKm(totalExpenses(),dist));}
 double distance(){Cursor c=db.raw("SELECT MIN(mileage),MAX(mileage) FROM (SELECT mileage FROM fuel WHERE vehicleId=? UNION ALL SELECT mileage FROM service WHERE vehicleId=? UNION ALL SELECT mileage FROM expense WHERE vehicleId=?)",new String[]{String.valueOf(active),String.valueOf(active),String.valueOf(active)});try{if(!c.moveToFirst())return 0;double a=c.getDouble(0),b=c.getDouble(1);return b>a?b-a:0;}finally{c.close();}}
 String fmt(double n){return String.format(Locale.getDefault(),"%.0f",n);}
 void advanceMileage(double km){if(km<=0)return;double cur=num(val("mileage","0"));if(km>cur){ContentValues v=new ContentValues();v.put("mileage",km);db.update("vehicle",v,"id=?",new String[]{String.valueOf(active)});}}
 boolean validDate(String s, boolean allowEmpty){if(s==null||s.trim().isEmpty())return allowEmpty;try{SimpleDateFormat f=new SimpleDateFormat("yyyy-MM-dd",Locale.US);f.setLenient(false);f.parse(s.trim());return true;}catch(Exception e){return false;}}
boolean validNonNegative(double x){return !Double.isNaN(x)&&!Double.isInfinite(x)&&x>=0;}
String attachment(){String a=pendingAttachment;if(a==null||a.isEmpty())a=getPreferences(0).getString("pending_attachment","");pendingAttachment="";getPreferences(0).edit().remove("pending_attachment").apply();return a;}
void warnMileageIfLower(double km,Runnable save){double cur=num(val("mileage","0"));if(km<0||Double.isNaN(km)){toast(t("Некорректный пробег","Invalid mileage"));return;}if(km<cur){new AlertDialog.Builder(this).setTitle(t("Пробег меньше текущего","Mileage is lower than current")) .setMessage(t("Сохранить меньший пробег для этой записи? Текущий пробег автомобиля не будет уменьшен автоматически.","Save this lower mileage for the record? The vehicle's current mileage will not be lowered automatically.")) .setNegativeButton(t("Отмена","Cancel"),null).setPositiveButton(t("Сохранить","Save"),(d,w)->save.run()).show();}else save.run();}
void serviceScreen(){header(t("Обслуживание","Service"),t("История и план обслуживания","Service history and plan"));Button add=btn(t("+ Добавить обслуживание","+ Add service"),blue);add.setOnClickListener(v->serviceDialog());add(add);addGap(10);EditText q=input(t("Поиск по обслуживанию…","Search service…"),"");add(q);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);add(list);Runnable run=()->{list.removeAllViews();String needle=q.getText().toString().trim().toLowerCase(Locale.ROOT);Cursor c=db.all("service",active);try{if(!c.moveToFirst()){LinearLayout e=card();e.addView(text(t("Пока нет записей об обслуживании","No service records yet"),14,true));Button b=btn(t("Добавить","Add"),blue);b.setOnClickListener(v->serviceDialog());e.addView(b);list.addView(e);return;}do{String title=c.getString(c.getColumnIndexOrThrow("title"));String cat=c.getString(c.getColumnIndexOrThrow("category"));String all=(title+" "+cat+" "+c.getString(c.getColumnIndexOrThrow("description"))).toLowerCase(Locale.ROOT);if(!needle.isEmpty()&&!all.contains(needle))continue;long id=c.getLong(0);LinearLayout x=card();x.addView(text(title,15,true));x.addView(small(c.getString(c.getColumnIndexOrThrow("date"))+" · "+fmt(c.getDouble(c.getColumnIndexOrThrow("mileage")))+" км"));x.addView(small(cat+" · "+money(c.getDouble(c.getColumnIndexOrThrow("cost")))+" ₽"));Button edit=btn(t("Изменить","Edit"),blue);edit.setOnClickListener(v->serviceDialog(id));x.addView(edit);list.addView(x);Space sp=new Space(this);list.addView(sp,new LinearLayout.LayoutParams(1,dp(7)));}while(c.moveToNext());}finally{c.close();}};q.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){run.run();}public void afterTextChanged(Editable e){}});run.run();}
void financeScreen(){header(t("Финансы","Finance"),t("Только сохранённые данные","Saved data only"));LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.HORIZONTAL);int[] days={7,30,90,365,0};String[] labels={"7д","30д","90д","1г","Всё"};for(int i=0;i<labels.length;i++){final int d=days[i];Button b=btn(labels[i],periodDays==d?blue:Color.rgb(55,78,104));b.setTextSize(11);b.setOnClickListener(v->{periodDays=d;render();});p.addView(b,new LinearLayout.LayoutParams(0,dp(45),1){{setMargins(dp(2),0,dp(2),0);}});}add(p);addGap(10);LinearLayout sum=card();double exp=sumPeriod("expense","amount");double fuel=sumPeriod("fuel","total");double svc=sumPeriod("service","cost");sum.addView(small(t("Расходы за период","Expenses for period")));sum.addView(text(money(exp+fuel+svc)+" ₽",30,true));sum.addView(small(t("ТО: ","Service: ")+money(svc)+" ₽ · "+t("Топливо: ","Fuel: ")+money(fuel)+" ₽ · "+t("Прочее: ","Other: ")+money(exp)+" ₽"));add(sum);addGap(10);Button e=btn(t("+ Добавить расход","+ Add expense"),blue);e.setOnClickListener(v->expenseDialog());add(e);Button f=btn(t("+ Добавить заправку","+ Add fuel"),Color.rgb(0,177,145));f.setOnClickListener(v->fuelDialog());add(f);addGap(10);sectionTitle(t("Стоимость километра","Cost per km"));add(infoCard(costKm()+" ₽/км",blue));addGap(10);sectionTitle(t("Последние расходы","Recent expenses"));listSimple("expense","title","amount");}
