 void statisticsScreen(){header(t("Статистика","Statistics"),t("Только фактические записи базы","Database records only"));LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.HORIZONTAL);int[] days={7,30,90,365,0};String[] labels={"7д","30д","90д","1г","Всё"};for(int i=0;i<labels.length;i++){final int d=days[i];Button b=btn(labels[i],periodDays==d?blue:Color.rgb(55,78,104));b.setTextSize(11);b.setOnClickListener(v->{periodDays=d;render();});p.addView(b,new LinearLayout.LayoutParams(0,dp(45),1){{setMargins(dp(2),0,dp(2),0);}});}add(p);addGap(10);double e=sumPeriod("expense","amount"),f=sumPeriod("fuel","total"),s=sumPeriod("service","cost");LinearLayout a=card();a.addView(text("Расходы",18,true));a.addView(text(money(e+f+s)+" ₽",29,true));a.addView(small("ТО "+money(s)+" ₽ · топливо "+money(f)+" ₽ · прочее "+money(e)+" ₽"));add(a);addGap(8);LinearLayout b=card();b.addView(text("Топливо",18,true));b.addView(text(periodDays>0?String.format(Locale.getDefault(),"%.1f л",sumPeriod("fuel","liters")):String.format(Locale.getDefault(),"%.1f л",sum("fuel","liters")),27,true));b.addView(small("Средний расход: "+consumption()+" л/100 км"));add(b);addGap(8);LinearLayout c=card();c.addView(text("Пробег",18,true));c.addView(text(distance()>0?fmt(distance())+" км":"Недостаточно данных",27,true));c.addView(small("Стоимость/км: "+costKm()+" ₽/км"));add(c);addGap(10);if(e+f+s<=0)add(small("Недостаточно данных для графиков за выбранный период."));}
void searchScreen(){header("Поиск","Поиск по локальной базе активного автомобиля");EditText q=input("Введите запрос…","");add(q);LinearLayout results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);add(results);Runnable run=()->{results.removeAllViews();String needle=q.getText().toString().trim();if(needle.isEmpty()){results.addView(small("Введите текст для поиска"));return;}String[] tables={"service","fuel","expense","reminder","issue","tire","document","part","service_center"};for(String table:tables){Cursor c=db.all(table,active);try{while(c.moveToNext()){StringBuilder z=new StringBuilder();for(int i=0;i<c.getColumnCount();i++){String s=c.getString(i);if(s!=null)z.append(' ').append(s);}if(z.toString().toLowerCase(Locale.ROOT).contains(needle.toLowerCase(Locale.ROOT))){LinearLayout card=card();card.addView(text(table+" · "+z.toString().trim(),13,true));results.addView(card);Space sp=new Space(this);results.addView(sp,new LinearLayout.LayoutParams(1,dp(6)));}}}finally{c.close();}}};q.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){run.run();}public void afterTextChanged(Editable e){}});run.run();}
