 void confirmDeleteVehicle(){new AlertDialog.Builder(this).setTitle("Удалить автомобиль?").setMessage("Будут удалены связанные записи этого автомобиля.").setNegativeButton("Отмена",null).setPositiveButton("Удалить",(d,w)->{String[] tables={"service","fuel","expense","reminder","issue","tire","document","part","service_center","activity"};for(String table:tables)db.delete(table,"vehicleId=?",new String[]{String.valueOf(active)});db.delete("vehicle","id=?",new String[]{String.valueOf(active)});Cursor c=db.raw("SELECT id FROM vehicle ORDER BY id LIMIT 1",null);try{active=c.moveToFirst()?c.getLong(0):-1;}finally{c.close();}getPreferences(0).edit().putLong("active",active).apply();if(active<0)showWelcome();else render();}).show();}
